// Procesar Orden por Voz con ElevenLabs
const body = $input.first().json.body;
return {
  tipo: 'ORDEN_VOZ',
  transcripcion: body.phrase || 'N/A',
  producto_solicitado: body.product?.nombre || body.product?.name || 'Desconocido',
  precio: body.product?.precio || body.product?.price || '0.00',
  canal_hardware: body.channel || 'A1 (Motor B)',
  estado_maquina: body.status || 'ESPERANDO_PAGO',
  timestamp: body.timestamp || new Date().toISOString(),
  mensaje_notificacion: `🎙️ [IAFantasma] Orden por voz recibida: ${body.product?.nombre || 'Producto'} (${body.product?.precio}). Transcripción: "${body.phrase}"`
};

// Procesar Pago NFC Confirmado (Tangem / Mifare)
const body = $input.first().json.body;
return {
  tipo: 'PAGO_NFC_EXITOSO',
  tarjeta_uid: body.card_uid || '4A:8F:12:9C',
  producto: body.product?.nombre || body.product?.name || 'Producto',
  monto: body.amount || '1.50 USDC',
  motor_activado: 'Motor B (Driver L298N)',
  timestamp: body.timestamp || new Date().toISOString(),
  mensaje_notificacion: `💳 [PAGO APROBADO] Tarjeta NFC UID: ${body.card_uid}. Despachando ${body.product?.nombre} mediante Motor B en Raspberry Pi Pico.`
};

// Confirmación de Entrega por Sensor IR
const body = $input.first().json.body;
return {
  tipo: 'DESPACHO_COMPLETADO',
  producto: body.product?.nombre || 'Producto',
  sensor_ir: 'GP14 (0 = Detectado)',
  resultado: 'EXITO',
  timestamp: body.timestamp || new Date().toISOString(),
  mensaje_notificacion: `✅ [ENTREGA CONFIRMADA] Sensor óptico IR detectó la caída del producto ${body.product?.nombre}. Máquina en reposo.`
};

// Alerta de Fallo / Timeout de Sensor IR
const body = $input.first().json.body;
return {
  tipo: 'ALERTA_DESPACHO',
  error: body.error || 'TIMEOUT_SIN_CAIDA',
  alerta: 'Revisar stock o atasco de espiral en el Motor B',
  timestamp: body.timestamp || new Date().toISOString(),
  mensaje_notificacion: `⚠️ [ALERTA DE DESPACHO] El sensor IR no detectó caída tras 8 segundos. Posible atasco o falta de stock.`
};
